def summarize(assigned, outcomes, unavailable=()):
    unavailable = set(unavailable)
    selected = set(assigned)
    if len(selected) != len(assigned) or not unavailable <= selected:
        raise ValueError('Assignment metadata is inconsistent')
    complete = []
    incomplete = []
    for path in assigned:
        result = outcomes.get(path)
        if path in unavailable or not isinstance(result, dict):
            incomplete.append(path)
            continue
        if result.get('status') != 'completed':
            incomplete.append(path)
            continue
        complete.append(path)
    status = 'completed' if complete and not incomplete else 'incomplete'
    return {'status': status, 'completed': complete, 'unavailable': sorted(unavailable)}


def display_status(summary):
    if summary['status'] == 'incomplete':
        return 'Some selected files could not be checked.'
    return 'All selected file checks completed.'

